	pekuangfeng_info: "Khi kết thúc lượt, bạn có thể bỏ một số lượng “Tinh” bất kỳ và chọn số lượng nhân vật tương ứng, cho đến trước khi bắt đầu lượt tiếp theo của bạn, khi những nhân vật này chịu sát thương Hỏa, sát thương này +1. Nếu làm vậy, bạn có thể khiến tất cả nhân vật lần lượt xem như sử dụng một 【Giết】 Hỏa không giới hạn khoảng cách.",
	petianlin: "Thiên Lâm",
	petianlin_info: "Khi kết thúc lượt, bạn có thể bỏ một số lượng “Tinh” bất kỳ và chọn số lượng nhân vật tương ứng, cho đến trước khi bắt đầu lượt tiếp theo của bạn, khi những nhân vật này chịu sát thương không phải Lôi, bạn ngăn ngừa sát thương này và bốc X lá bài (X là số lượng bài “Tinh” trên bài tướng của bạn).",
