	peshelie_info: "① Giai đoạn Bốc Bài, bạn có thể đổi thành tiết lộ năm lá bài trên cùng bộ bài, sau đó bạn nhận được mỗi hoa một lá bài. ② Khi bạn gây sát thương, bạn có thể phát động một lần 【Thiệp Liệp①】.",
	pegongxin: "Công Tâm",
	pegongxin_info: "① Giai đoạn Xuất Bài giới hạn một lần, bạn có thể xem bài trên tay của một nhân vật khác và tiết lộ một lá bài ♥️ trong đó, sau đó đặt lá bài này lên đỉnh bộ bài hoặc bỏ nó. ② Khi bạn chịu sát thương, bạn có thể phát động một lần 【Công Tâm①】 nhắn vào nguồn gây sát thương.",
