	peyeyan: "Nghiệp Diêm",
	peyeyan_info: "Kỹ năng giới hạn, giai đoạn Xuất Bài, bạn có thể phân phối tối đa X điểm sát thương Hỏa cho tối đa ba nhân vật, nếu có nhân vật chết vì kỹ năng này, bạn thiết lập lại kỹ năng này và khiến X-1 (X ban đầu là 3).",
	hl_shen_lvbu: "Hổ Lao Thần Lã Bố",
