	zc26_bagua_skill: "Hồn·Bát Quái Trận",
	zc26_bagua_skill_info: "Khi bạn cần sử dụng hoặc đánh ra 【Tránh】, bạn có thể thực hiện một lần phán định, nếu kết quả là đỏ, xem như đã dùng hoặc đánh ra; trước khi phán định, bạn có thể khiến một nhân vật đã chết bói toán 3.",
