	zc26_lingling_skill: "Linh Linh",
	zc26_lingling_skill_info: "Giai đoạn Chuẩn Bị, bạn phải gây cho một nhân vật 1 điểm sát thương Lôi; khi kết thúc mỗi vòng, tất cả nhân vật đã chết đồng thời bí mật chọn nhà trên hoặc nhà dưới, sau đó theo thứ tự (chết từ trước đến sau) lần lượt di chuyển bài này đến khu vực tương ứng của nhân vật đã chọn.",
	le_shen_jiaxu: "Thần Giả Hủ",
