	jxlianpo_info: "Kỹ năng khóa. ① Nếu phe lớn nhất trên bàn là: Phản tặc, giới hạn bài trên tay của nhân vật khác -1, tất cả nhân vật có giới hạn số lần dùng 【Giết】 và phạm vi tấn công +1; Chủ trung, nhân vật khác không thể dùng 【Đào】 cho nhân vật khác ngoài bản thân. Nếu có nhiều phe lớn nhất, sau khi nhân vật khác chết, nguồn gây sát thương bốc hai lá bài hoặc hồi phục 1 điểm thể lực. ② Khi bắt đầu mỗi vòng, bạn tiết lộ một thẻ thân phận chưa tham gia trò chơi hoặc đã chết, trong vòng này được xem là số nhân vật của phe tương ứng với thẻ thân phận đó +1.",
